window.SIM_DATA = {"cases": [{"id": "sc-ards", "name": "2-year-old girl · 10 kg", "kg": 10, "kind": "ards", "title": "2-year-old girl · 10 kg", "setting": "Pneumonia → ARDS · ER to PICU, three days", "stages": [{"id": "ar0", "t": "Day 5 · your ER", "story": "Cough, cold and fever for 5 days, fast breathing for 2. Admitted at a nearby hospital on 5 L/min oxygen by face mask, IV fluids and IV ceftriaxone, then referred. In your ER she is on a non-rebreathing mask at 15 L/min.", "vit": [["HR", "150"], ["RR", "55"], ["SpO₂", "92% on NRM 15 L/min"], ["BP", "90/55"], ["CRT", "2 s"], ["Temp", "38.8 °C"]], "exam": ["Alert, irritable, drinking", "Subcostal and intercostal indrawing, nasal flaring", "Bilateral crackles, no wheeze, equal air entry"], "vent": "", "abg": [["pH", "7.35"], ["PaCO₂", "56"], ["PaO₂", "70"], ["HCO₃", "22"], ["Lactate", "1.0"]], "img": "assets/cxr/cxr-scen01-niv.jpg", "imgCap": "Chest X-ray · AP · patchy opacities in both lungs", "table": null, "q": "What respiratory support now?", "opts": [["Start NIV (CPAP or bilevel) and set a failure plan", 1, "She is hypoxaemic with early CO₂ retention, but awake, protecting her airway and perfusing well. A trial of NIV is reasonable. Decide before you start what failure looks like: a time limit, and the numbers that will make you intubate.", 0], ["Intubate now", 0, "Not yet. pH 7.35, alert, stable circulation. Intubation carries its own risks. But stay at the bedside: NIV fails often in pneumonia, and the time to intubate is before she is in shock.", 1], ["Continue the mask and add nebulised salbutamol", 0, "There is no wheeze. Crackles and a patchy X-ray mean fluid-filled alveoli, not narrowed airways. A bronchodilator will not help, and 15 L/min by mask has no more to give.", 2], ["Switch to high-flow nasal cannula", 0, "Defensible, but she already needs a 15 L/min non-rebreather and her CO₂ is 56. Pressure (PEEP) is what recruits wet alveoli; NIV delivers it reliably.", 1]], "teach": "Set the ceiling before you start NIV. Reassess at 1 and 2 hours: rising CO₂, falling pH, FiO₂ climbing past 0.6, rising heart rate or any sign of shock means the trial has failed.", "teachList": [], "phys": {"C": 4.4, "R": 25, "kg": 10, "kind": "ards", "own": 55.0, "anc": {"set": {"iface": "MASK", "mode": "Mask", "v": {"l": 15}}, "mon": [["HR", "150"], ["RR", "55"], ["SpO₂", "92"], ["BP", "90/55"], ["CRT", "2 s"], ["Temp", "38.8 °C"]], "gas": {"pH": 7.35, "PaCO₂": 56.0, "PaO₂": 70.0, "HCO₃": 22.0}}}, "rule": {"iface": {"MASK": 2, "HFNC": 1, "NIV": 0, "VENT": 1}, "knobs": {"cp": [5, 8, 4, 10], "ep": [5, 8, 4, 10], "ip": [10, 16, 8, 20], "o": [60, 100, 40, 100]}}, "ifaces": ["MASK", "HFNC", "NIV", "VENT"], "intub": false, "mon": [["HR", "150"], ["RR", "55"], ["SpO₂", "92"], ["BP", "90/55"], ["CRT", "2 s"], ["Temp", "38.8 °C"]]}, {"id": "ar1", "t": "2 hours on NIV", "story": "On NIV with PEEP 6, pressure support 10, FiO₂ 0.85. The nurse calls you: she is working harder and her hands are cold.", "vit": [["HR", "180"], ["RR", "40–50"], ["SpO₂", "88–90%"], ["ABP", "86/45"], ["CRT", "4 s"], ["Temp", "38.5 °C"]], "exam": ["Drowsy between breaths, grunting", "Cold peripheries, weak pulses", "Severe indrawing, head bobbing"], "vent": "NIV · PEEP 6 · PS 10 · FiO₂ 0.85", "abg": [["pH", "7.25"], ["PaCO₂", "65"], ["PaO₂", "55"], ["HCO₃", "18"], ["Lactate", "2.0"]], "img": "", "imgCap": "", "table": null, "q": "What now?", "opts": [["Intubate", 1, "NIV has failed: CO₂ up from 56 to 65, pH down to 7.25, PaO₂ 55 on FiO₂ 0.85, and now shock. Prepare for a hypoxic, unstable intubation: preoxygenate on the NIV, give a 10 mL/kg bolus and have a push-dose pressor drawn up, choose a cuffed tube, most experienced hands on the laryngoscope.", 0], ["Raise PS to 14 and PEEP to 8", 0, "Escalating a failing trial costs time she does not have. She is in shock with a falling pH. More pressure on a tired, drowsy child risks aspiration and an arrest on the mask.", 3], ["Fluid bolus and repeat the gas in an hour", 0, "The bolus is right; the hour is not. Her lungs are failing, not just her circulation. Fix the circulation while you prepare to intubate.", 2], ["Switch to high-flow nasal cannula", 0, "A step down in support for a child who is failing a step up.", 3]], "teach": "Intubation in ARDS is a resuscitation, not a procedure. Expect desaturation on induction and hypotension after positive pressure. Fluids, pressor, cuffed tube, and a plan for the first ventilator settings before the drugs go in.", "teachList": [], "phys": {"C": 4.4, "R": 25, "kg": 10, "kind": "ards", "own": 40.0, "anc": {"set": {"iface": "NIV", "mode": "ST", "v": {"ip": 16, "ep": 6, "br": 20, "ti": 0.7, "o": 85}}, "mon": [["HR", "180"], ["RR", "40–50"], ["SpO₂", "88–90"], ["ABP", "86/45"], ["CRT", "4 s"], ["Temp", "38.5 °C"]], "gas": {"pH": 7.25, "PaCO₂": 65.0, "PaO₂": 55.0, "HCO₃": 18.0}}}, "rule": {"iface": {"MASK": 3, "HFNC": 3, "NIV": 3, "VENT": 0}, "knobs": {"vt": [60, 80, 50, 100], "pe": [6, 10, 5, 14], "rr": [25, 35, 20, 40], "ti": [0.5, 0.8, 0.4, 1.0], "o": [80, 100, 60, 100], "pi": [12, 20, 10, 25]}}, "ifaces": ["MASK", "HFNC", "NIV", "VENT"], "intub": false, "mon": [["HR", "180"], ["RR", "40–50"], ["SpO₂", "88–90"], ["ABP", "86/45"], ["CRT", "4 s"], ["Temp", "38.5 °C"]]}, {"id": "ar2", "t": "Intubated · first settings", "story": "A 4.5 cuffed tube is in, equal air entry, end-tidal CO₂ confirmed. She is sedated and paralysed. The ventilator is waiting.", "vit": [], "exam": [], "vent": "", "abg": [], "img": "assets/cxr/cxr-scen01-intubated.jpg", "imgCap": "Post-intubation film · tube at T2 · bilateral opacities", "table": null, "q": "Which first settings?", "opts": [["PRVC or VC · VT 60–80 mL (6–8 mL/kg) · PEEP 7 · RR 30 · I:E 1:2 · FiO₂ 1.0 then wean", 1, "Any mode is acceptable; the limits matter more than the mode. Here PRVC gives a decelerating flow with a guaranteed volume. Start FiO₂ at 1.0 and taper to SpO₂ 88–94%. PEEP 7 is a starting point, not the answer: titrate it next. Set the rate and I:E by watching the flow–time scalar so expiratory flow reaches zero before the next breath.", 0], ["VC · VT 100 mL (10 mL/kg) · PEEP 5 · RR 20", 0, "Ten mL/kg into a small, wet lung overstretches the open alveoli. The baby lung in ARDS needs small breaths and enough PEEP.", 2], ["PC · Pinsp 30 · PEEP 5 · RR 40", 0, "A 30 cmH₂O driving pressure on a stiff lung will deliver too large a volume at first, and a rate of 40 with I:E 1:2 leaves only 1 second to exhale.", 2], ["HFOV straight away", 0, "Not first-line. Conventional lung-protective ventilation with a titrated PEEP comes first; HFOV is a rescue when that fails.", 1]], "teach": "The ARDS triad: tidal volume 6–8 mL/kg, plateau ≤ 28–30 cmH₂O, driving pressure ≤ 15 cmH₂O. The mode is a vehicle for those limits.", "teachList": [], "phys": {"C": 3.9, "R": 25, "kg": 10, "kind": "ards", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "PRVC", "v": {"vt": 75.0, "pe": 7.0, "rr": 30.0, "ti": 0.67, "o": 100}}, "mon": [["HR", "166"], ["RR", "30"], ["SpO₂", "92"], ["ABP", "92/49"], ["CRT", "3 s"], ["Temp", "38.5 °C"]], "gas": {"pH": 7.3, "PaCO₂": 50.0, "PaO₂": 65.0, "HCO₃": 24.0}}}, "rule": {"iface": {"VENT": 0}, "knobs": {"vt": [60, 80, 50, 100], "pe": [6, 10, 5, 14], "rr": [25, 35, 20, 40], "ti": [0.5, 0.8, 0.4, 1.0], "o": [80, 100, 60, 100], "pi": [12, 20, 10, 25]}}, "ifaces": ["VENT"], "intub": true, "mon": [["HR", "180"], ["RR", "30"], ["SpO₂", "88–90"], ["ABP", "86/45"], ["CRT", "4 s"], ["Temp", "38.5 °C"]]}, {"id": "ar3", "t": "30 minutes later", "story": "Settled on PRVC. The nurse has the first ventilator gas.", "vit": [["HR", "167"], ["SpO₂", "88%"], ["ABP", "88/50"], ["Temp", "38.2 °C"]], "exam": [], "vent": "PRVC · VT 75 mL · RR 30 · I:E 1:2 · PEEP 7 · FiO₂ 1.0 · Ppeak 30 · Pplat 26", "abg": [["pH", "7.30"], ["PaCO₂", "50"], ["PaO₂", "65"], ["HCO₃", "24"]], "img": "", "imgCap": "", "table": null, "q": "Oxygenation is poor on FiO₂ 1.0. Which setting do you change first?", "opts": [["Titrate PEEP upward in steps, watching compliance, SpO₂ and blood pressure", 1, "FiO₂ is already maximal, so the other lever for oxygenation is mean airway pressure, and PEEP is the safest way to raise it. Go up in 2 cmH₂O steps every few minutes and record VT, plateau, driving pressure, SpO₂ and BP at each step.", 0], ["Increase FiO₂", 0, "It is already 1.0.", 1], ["Increase VT to 100 mL", 0, "More volume raises the plateau and driving pressure. It treats the oxygen number by stretching the lung.", 2], ["Increase the rate to 40", 0, "Rate clears CO₂; it does little for oxygen. At 40 with I:E 1:2 the expiratory time falls to 1 second and gas may start to trap.", 2]], "teach": "Oxygenation depends on FiO₂ and mean airway pressure. Mean airway pressure is set by PEEP, inspiratory time and peak pressure. In a stiff lung, PEEP is the lever to pull first.", "teachList": [], "phys": {"C": 3.9, "R": 25, "kg": 10, "kind": "ards", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "PRVC", "v": {"vt": 75.0, "pe": 7.0, "rr": 30.0, "ti": 0.67, "o": 100}}, "mon": [["HR", "167"], ["RR", "30"], ["SpO₂", "88"], ["ABP", "88/50"], ["Temp", "38.2 °C"]], "gas": {"pH": 7.3, "PaCO₂": 50.0, "PaO₂": 65.0, "HCO₃": 24.0}}}, "rule": {"iface": {"VENT": 0}, "knobs": {"vt": [60, 80, 50, 100], "pe": [9, 12, 7, 14], "rr": [25, 35, 20, 40], "ti": [0.5, 0.8, 0.4, 1.0], "o": [80, 100, 60, 100], "pi": [12, 20, 10, 25]}}, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "167"], ["RR", "30"], ["SpO₂", "88"], ["ABP", "88/50"], ["Temp", "38.2 °C"]]}, {"id": "ar4", "t": "PEEP titration", "story": "You go up in steps of 2 cmH₂O on PRVC, waiting about 4 minutes at each step. This is what the nurse writes down.", "vit": [], "exam": [], "vent": "", "abg": [], "img": "", "imgCap": "", "table": {"head": ["VT", "PEEP", "Pplat", "ΔP", "FiO₂", "Crs", "EtCO₂", "SpO₂", "BP"], "rows": [["75", "6", "30", "24", "1.0", "3.1", "36", "90", "110/70"], ["60", "8", "26", "18", "1.0", "3.3", "42", "92", "110/70"], ["60", "10", "26", "16", "1.0", "3.8", "45", "94", "110/70"], ["60", "12", "26", "14", "1.0", "4.3", "45", "96", "110/70"], ["60", "14", "30", "16", "1.0", "3.8", "50", "96", "100/70"], ["60", "12", "26", "14", "1.0", "4.3", "45", "96", "110/70"]], "note": "One row per step, about 4 minutes apart, rate 30 throughout. Crs = compliance = VT ÷ ΔP, mL/cmH₂O. ΔP = Pplat − PEEP. A 10 kg example; VT held at 6 mL/kg from the second step."}, "q": "Which PEEP do you settle on?", "opts": [["12 cmH₂O", 1, "At 12 the compliance is best (4.3 mL/cmH₂O), the driving pressure lowest (14), SpO₂ 96% and the BP unchanged. One step higher the plateau jumped to 30, compliance fell to 3.8 and the BP dipped: that is overdistension. Come back down to the best step.", 0], ["14 cmH₂O", 0, "SpO₂ did not improve, but the plateau rose to 30, compliance fell from 4.3 to 3.8 and the BP dropped. The lung is overdistended and the heart is being squeezed.", 2], ["8 cmH₂O", 0, "Compliance was still climbing and FiO₂ was still 0.8. The lung had more to recruit.", 1], ["10 cmH₂O", 0, "Close. But at 12 the compliance was better and the driving pressure lower at the same VT, with no cost in blood pressure.", 1]], "teach": "Best-compliance PEEP: step up until compliance stops improving or driving pressure starts to rise, then step back. Other ways to pick PEEP: the ARDSNet FiO₂–PEEP table, a decremental trial after recruitment, the stress index, or the lower inflection point of the pressure–volume loop. Whichever you use, watch the blood pressure.", "teachList": [], "phys": {"C": 3.9, "R": 25, "kg": 10, "kind": "ards", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "PRVC", "v": {"vt": 75.0, "pe": 7.0, "rr": 30.0, "ti": 0.67, "o": 100}}, "mon": [["HR", "167"], ["RR", "30"], ["SpO₂", "88"], ["ABP", "88/50"], ["Temp", "38.2 °C"]], "gas": {}}}, "rule": null, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "167"], ["RR", "30"], ["SpO₂", "88"], ["ABP", "88/50"], ["Temp", "38.2 °C"]]}, {"id": "ar5", "t": "PEEP 12 · still on FiO₂ 1.0", "story": "An hour after the titration.", "vit": [["HR", "130"], ["SpO₂", "91%"], ["ABP", "88/50"]], "exam": [], "vent": "PRVC · VT 75 mL · RR 30 · I:E 1:2 · PEEP 12 · FiO₂ 1.0 · Pplat 26", "abg": [["pH", "7.32"], ["PaCO₂", "50"], ["PaO₂", "65"], ["HCO₃", "24"]], "img": "", "imgCap": "", "table": null, "q": "Can another ventilator setting help oxygenation?", "opts": [["Lengthen the inspiratory time (I:E towards 1:1.5 or 1:1), checking the expiratory flow still reaches zero", 1, "A longer Ti raises mean airway pressure without raising the peak or the PEEP. The flow–time scalar shows expiration ending well before the next breath, so there is time to spare. The time constant (resistance × compliance) is short in a stiff lung, which is why it empties quickly and tolerates a shorter expiration.", 0], ["Raise the rate to 40", 0, "Rate helps CO₂, not oxygen, and the CO₂ is 50 already. It also shortens expiration.", 2], ["Raise the VT to 100 mL", 0, "Driving pressure goes up. Oxygen barely moves.", 2], ["Switch to HFOV", 0, "Not yet. Oxygenation index is about 26 (mean airway pressure 17 × FiO₂ 100 ÷ PaO₂ 65). There are conventional moves left: inspiratory time, proning, fluid balance.", 1]], "teach": "Mean airway pressure = the area under the pressure–time curve. PEEP lifts the whole curve; a longer Ti widens the plateau. Both raise MAP. Always confirm on the flow scalar that expiration is complete before you lengthen inspiration.", "teachList": [], "phys": {"C": 5.4, "R": 25, "kg": 10, "kind": "ards", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "PRVC", "v": {"vt": 75.0, "pe": 12.0, "rr": 30.0, "ti": 0.67, "o": 100}}, "mon": [["HR", "130"], ["RR", "30"], ["SpO₂", "91"], ["ABP", "88/50"]], "gas": {"pH": 7.32, "PaCO₂": 50.0, "PaO₂": 65.0, "HCO₃": 24.0}}}, "rule": {"iface": {"VENT": 0}, "knobs": {"ti": [0.75, 1.0, 0.6, 1.2], "vt": [60, 80, 50, 100], "pe": [10, 12, 8, 14], "rr": [25, 32, 20, 40], "o": [80, 100, 60, 100], "pi": [12, 20, 10, 25]}}, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "130"], ["RR", "30"], ["SpO₂", "91"], ["ABP", "88/50"]]}, {"id": "ar6", "t": "6 hours · fighting the ventilator", "story": "The high-pressure alarm keeps sounding. She is moving all four limbs and coughing on the tube. Paralysis has worn off.", "vit": [["HR", "190"], ["RR", "60 (set 30)"], ["SpO₂", "88–90%"], ["ABP", "95/55"]], "exam": ["Breathing at 60, pulling on every breath", "Equal air entry, tube at the same mark, suctioned clear", "Coughing, grimacing, moving all limbs"], "vent": "PRVC · VT 75 mL · RR 30 · PEEP 12 (titrated) · FiO₂ 0.8 · intermittent Ppeak alarm · no auto-PEEP", "abg": [], "img": "", "imgCap": "", "table": null, "q": "What next?", "opts": [["Rule out the tube, secretions and pneumothorax, then deepen sedation to Ramsay 3–4; add intermittent neuromuscular blockade only if she still fights", 1, "First the quick checks: tube position, suction, breath sounds, a bedside ultrasound for pneumothorax, pain, a full bladder. Then sedation: fentanyl with a midazolam infusion, or morphine with intermittent midazolam or ketamine, titrated to Ramsay 3–4. Asynchrony at 60 breaths a minute wastes oxygen, drops the saturation and stretches the lung with every stacked breath.", 0], ["Start a continuous neuromuscular blocker infusion first", 0, "Paralysis without adequate sedation is cruel and masks pain. Sedate first; use the lowest dose of blocker for the shortest time if she still fights.", 2], ["Raise the set rate to 60 to match her", 0, "The machine would then deliver 60 set breaths on top of a child who is pulling. The rate is a symptom, not the problem.", 2], ["Extubate to NIV because she is awake", 0, "She is on PEEP 12 and FiO₂ 0.8 with a plateau of 26. Awake is not the same as ready.", 3]], "teach": "Sedation goal in moderate–severe ARDS: comfortable, not fighting, tolerating the breath. Neuromuscular blockade is a tool for severe asynchrony or refractory hypoxaemia in the first 48 hours, at the lowest effective dose, stopped as soon as possible to prevent myopathy.", "teachList": [], "phys": {"C": 4.7, "R": 25, "kg": 10, "kind": "ards", "own": 60.0, "anc": {"set": {"iface": "VENT", "mode": "PRVC", "v": {"vt": 75.0, "pe": 12.0, "rr": 30.0, "ti": 0.67, "o": 80}}, "mon": [["HR", "190"], ["RR", "60"], ["SpO₂", "88–90"], ["ABP", "95/55"]], "gas": {}}, "trig": 60.0}, "rule": null, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "190"], ["RR", "60"], ["SpO₂", "88–90"], ["ABP", "95/55"]]}, {"id": "ar7", "t": "Day 2 · the chart beyond the ventilator", "story": "Settled on the ventilator overnight. The morning round brings the labs, the fluid chart and an echo.", "vit": [["HR", "140"], ["SpO₂", "90%"], ["ABP", "90/52"], ["Fluid balance", "+350 mL since admission"]], "exam": ["Hb 9 g/dL · TLC 20,000 (N55 L45) · platelets 1.6 lakh", "CRP 96 mg/L · procalcitonin 70", "Flu panel and adenovirus PCR negative · electrolytes, renal, liver and coagulation normal", "Echo: normal contractility, normal chambers, IVC adequate, no TR, normal right heart", "Abdomen soft, not distended"], "vent": "PRVC · VT 75 mL · RR 30 · PEEP 12 · FiO₂ 0.8 · Pplat 26 · MAP 17", "abg": [["pH", "7.30"], ["PaCO₂", "58"], ["PaO₂", "65"], ["HCO₃", "24"]], "img": "assets/cxr/cxr-scen01-worse.jpg", "imgCap": "Day 2 film · denser, more confluent opacities", "table": null, "q": "Beyond the ventilator, what matters most this morning?", "opts": [["Fluids: stop the positive creep and aim even-to-negative once perfusing; review the antibiotics against the cultures; keep the abdomen decompressed; transfuse only below Hb 7", 1, "Six things outside the ventilator change the lung: fluid balance, infection control, haemoglobin, haemodynamics, abdominal distension and chest-wall compliance. She is +350 mL with a wet lung and a normal heart, so a careful diuresis is reasonable. A rising procalcitonin with a negative viral panel means bacterial pneumonia: check the cultures and the antibiotic choice.", 0], ["Give a 20 mL/kg bolus for the low-normal blood pressure", 0, "The echo shows an adequate IVC and a normal heart. More fluid goes into the lung. Perfusion is adequate; the BP does not need a bolus.", 2], ["Transfuse to Hb 12 to improve oxygen delivery", 0, "Hb 9 is above the transfusion threshold of 7 for a stable child. Blood adds volume and lung injury risk.", 2], ["Start steroids and IVIG", 0, "No indication here. Neither is routine for paediatric ARDS from bacterial pneumonia.", 1]], "teach": "Every extra 10 mL/kg of fluid is edema in a lung that is already wet. In ARDS, after the first resuscitation, a conservative fluid strategy shortens ventilation.", "teachList": [], "phys": {"C": 5.4, "R": 25, "kg": 10, "kind": "ards", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "PRVC", "v": {"vt": 75.0, "pe": 12.0, "rr": 30.0, "ti": 0.67, "o": 80}}, "mon": [["HR", "140"], ["RR", "30"], ["SpO₂", "90"], ["ABP", "90/52"], ["Fluid balance", "+350 mL since admission"]], "gas": {"pH": 7.3, "PaCO₂": 58.0, "PaO₂": 65.0, "HCO₃": 24.0}}}, "rule": null, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "140"], ["RR", "30"], ["SpO₂", "90"], ["ABP", "90/52"], ["Fluid balance", "+350 mL since admission"]]}, {"id": "ar8", "t": "Day 2 evening · OI 26", "story": "Despite the best PEEP, a longer Ti, sedation and a drier chart, she is back on FiO₂ 1.0.", "vit": [["HR", "145"], ["SpO₂", "88%"], ["ABP", "88/50"], ["OI", "26"], ["P/F", "65"]], "exam": [], "vent": "PRVC · VT 75 mL · RR 30 · PEEP 12 · FiO₂ 1.0 · Ppeak 30 · Pplat 28 · MAP 17", "abg": [["pH", "7.30"], ["PaCO₂", "58"], ["PaO₂", "65"], ["HCO₃", "24"]], "img": "", "imgCap": "", "table": null, "q": "What else can be done?", "opts": [["Prone her, for 16 or more hours a day, with a turning checklist", 1, "Proning recruits the dorsal lung, drains secretions and spreads the ventilation more evenly. Use a checklist: tube secured and depth noted, lines and drains protected, eyes taped and padded, pressure points padded, head turned two-hourly, one person owning the airway during every turn.", 0], ["HFOV now", 0, "A reasonable rescue, but prone first: the plateau is 28, so there is no barotrauma forcing a mode change yet. HFOV is the next step if proning fails.", 1], ["Inhaled nitric oxide", 0, "Improves the number for a while; no mortality benefit. A bridge for pulmonary hypertension or on the way to ECMO, not a treatment for pneumonia.", 1], ["Refer for ECMO today", 0, "Talk to the ECMO centre early, yes. But OI 26 with proning not yet tried is not an ECMO indication. Sustained OI above 40 despite the best conventional care is.", 1]], "teach": "Complications of prone position: device displacement, vomiting, loss of venous access, accidental extubation, tube displacement or obstruction, haemodynamic instability, brachial plexus injury, pressure ulcers. Every one of them is prevented by the checklist.", "teachList": ["Tube: secure, note the depth, suction before the turn", "Lines and drains: untangle, clamp what can be clamped", "Eyes: closed and padded", "Pressure points: forehead, chest, pelvis, knees padded", "Head turned 2-hourly; arms in the swimmer position", "Abort criteria agreed before the turn"], "phys": {"C": 4.7, "R": 25, "kg": 10, "kind": "ards", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "PRVC", "v": {"vt": 75.0, "pe": 12.0, "rr": 30.0, "ti": 0.67, "o": 100}}, "mon": [["HR", "145"], ["RR", "30"], ["SpO₂", "88"], ["ABP", "88/50"], ["OI", "26"], ["P/F", "65"]], "gas": {"pH": 7.3, "PaCO₂": 58.0, "PaO₂": 65.0, "HCO₃": 24.0}}}, "rule": null, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "145"], ["RR", "30"], ["SpO₂", "88"], ["ABP", "88/50"], ["OI", "26"], ["P/F", "65"]]}, {"id": "ar9", "t": "Day 3 · prone · which numbers to accept", "story": "Prone for 14 hours. The gas is worse but the blood pressure is steady.", "vit": [["HR", "150"], ["SpO₂", "86%"], ["ABP", "90/55"], ["OI", "33"]], "exam": [], "vent": "PRVC · VT 65 mL · RR 25 · PEEP 12 · FiO₂ 1.0 · PIP 32 · MAP 18", "abg": [["pH", "7.20"], ["PaCO₂", "75"], ["PaO₂", "55"], ["HCO₃", "17"]], "img": "", "imgCap": "", "table": null, "q": "What PaO₂ and PaCO₂ are acceptable now?", "opts": [["Accept SpO₂ 88–92% (PaO₂ 55–80) and a PaCO₂ of 75 while the pH stays ≥ 7.20; escalate to HFOV and call the ECMO centre if it drifts further", 1, "Permissive hypoxaemia and permissive hypercapnia protect the lung from the pressures that normal numbers would demand. pH 7.20 is the floor. She is at it, with an OI of 33 after proning: time to move to HFOV and to speak to ECMO before the OI reaches 40.", 0], ["Raise VT to 100 mL to normalise the CO₂", 0, "A normal CO₂ bought with a plateau above 30 is a bad trade. Driving pressure is what kills.", 2], ["Raise PEEP to 16 to reach SpO₂ 95%", 0, "The best-compliance PEEP was 12 and she is already on 10 with a PIP of 32. More PEEP now means overdistension and a falling cardiac output.", 2], ["Hyperventilate at a rate of 45", 0, "More breaths at the same driving pressure stretch the lung 45 times a minute and trap gas.", 2]], "teach": "Permissive hypercapnia is contraindicated with raised intracranial pressure, pulmonary hypertension, severe right-heart failure and some congenital heart disease. Permissive hypoxaemia assumes a normal haemoglobin and cardiac output: check both.", "teachList": [], "phys": {"C": 4.1, "R": 25, "kg": 10, "kind": "ards", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "PRVC", "v": {"vt": 65.0, "pe": 12.0, "rr": 25.0, "ti": 0.8, "o": 100}}, "mon": [["HR", "150"], ["RR", "25"], ["SpO₂", "86"], ["ABP", "90/55"], ["OI", "33"]], "gas": {"pH": 7.2, "PaCO₂": 75.0, "PaO₂": 55.0, "HCO₃": 17.0}}}, "rule": {"iface": {"VENT": 0}, "knobs": {"vt": [55, 75, 50, 90], "pe": [8, 12, 6, 14], "rr": [20, 30, 16, 40], "ti": [0.6, 0.9, 0.5, 1.1], "o": [80, 100, 60, 100], "pi": [12, 20, 10, 25]}}, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "150"], ["RR", "25"], ["SpO₂", "86"], ["ABP", "90/55"], ["OI", "33"]]}], "debrief": ["NIV is a trial with a stop rule. Write the failure criteria down before you start.", "Intubation in ARDS is a resuscitation: fluids, pressor and a cuffed tube ready.", "Any mode works. The limits are what matter: VT 6–8 mL/kg, plateau ≤ 28–30, driving pressure ≤ 15.", "Oxygenation = FiO₂ + mean airway pressure. PEEP first, then inspiratory time, both checked against the flow scalar.", "Titrate PEEP to best compliance or lowest driving pressure, and watch the blood pressure.", "Asynchrony: check the tube, secretions and chest first, then sedation, then the briefest paralysis.", "Outside the ventilator: fluids, infection, haemoglobin, haemodynamics, abdomen, chest wall.", "Rescue ladder: prone → HFOV → ECMO discussion. Accept SpO₂ 88–92% and a high CO₂ with pH ≥ 7.20."], "pocus": {"heart": ["assets/pocus/a4c-normal.mp4", "Apical four-chamber: normal size and squeeze; no effusion."], "ivc": ["assets/pocus/ivc-normal.mp4", "IVC normal size, varies with the breath."], "subcostal": ["assets/pocus/subcostal-normal.mp4", "Subcostal: no pericardial effusion."], "lung": [null, "Bilateral B-lines; posterior consolidation with air bronchograms; lung sliding present both sides."]}}, {"id": "sc-asthma", "name": "5-year-old boy · 20 kg", "kg": 20, "kind": "asthma", "title": "5-year-old · 20 kg", "setting": "Acute severe asthma · ER to PICU, two days", "stages": [{"id": "as0", "t": "Arrives in the ER", "story": "Known asthma, on an inhaled steroid he rarely takes. Two days of cough and wheeze, worse overnight. Three salbutamol nebulisers, ipratropium, IV hydrocortisone and IV magnesium in the ambulance and the ER over the last hour.", "vit": [["HR", "160"], ["RR", "48"], ["SpO₂", "86% on NRM 15 L/min"], ["BP", "100/60"], ["Temp", "37.2 °C"]], "exam": ["Drowsy, slow to respond, cannot speak", "Hyperinflated chest, barely any wheeze: a quiet chest", "Severe accessory muscle use, tracheal tug"], "vent": "", "abg": [], "img": "", "imgCap": "", "table": null, "q": "Intubate?", "opts": [["Yes, now. This is a clinical decision", 1, "No blood gas defines the need to intubate in asthma. Exhaustion with an altered mental state after maximal therapy is the indication, and a quiet chest in a drowsy child is the loudest sign. Prepare for a difficult, hypotensive intubation.", 0], ["Get a blood gas first and decide on the PCO₂", 0, "A normal or high CO₂ in a tiring asthmatic is already ominous, but the decision is clinical. Waiting for the gas costs minutes he does not have.", 2], ["Trial of NIV", 0, "He is drowsy and cannot protect his airway. NIV needs an awake, cooperative child.", 3], ["More nebulisers and magnesium, review in 30 minutes", 0, "He has had maximal therapy and is getting worse. Poor response plus altered sensorium is the indication.", 3]], "teach": "Indications to ventilate in asthma: progressive exhaustion with altered mental status (the main one), poor response to therapy, severe hypoxaemia, rising PCO₂, cardiorespiratory arrest. Not a number.", "teachList": ["Exhaustion with altered mental status", "Poor response to maximal therapy", "Severe hypoxaemia", "Rising PCO₂", "Altered sensorium", "Cardiorespiratory arrest"], "phys": {"C": 8, "R": 60, "kg": 20, "kind": "asthma", "own": 48.0, "anc": {"set": {"iface": "MASK", "mode": "Mask", "v": {"l": 15}}, "mon": [["HR", "160"], ["RR", "48"], ["SpO₂", "86"], ["BP", "100/60"], ["Temp", "37.2 °C"]], "gas": {}}}, "rule": {"iface": {"MASK": 2, "HFNC": 2, "NIV": 3, "VENT": 0}, "knobs": {"vt": [120, 160, 100, 200], "rr": [10, 16, 8, 20], "ti": [0.6, 1.0, 0.5, 1.2], "pe": [0, 5, 0, 8], "o": [60, 100, 40, 100], "pi": [15, 25, 10, 30], "te": [3.5, 99, 2, 99]}}, "ifaces": ["MASK", "HFNC", "NIV", "VENT"], "intub": false, "mon": [["HR", "160"], ["RR", "48"], ["SpO₂", "86"], ["BP", "100/60"], ["Temp", "37.2 °C"]]}, {"id": "as1", "t": "Induction and the tube", "story": "IV access ×2, 20 mL/kg of fluid running, adrenaline drawn up, bag and mask with PEEP valve ready, two sizes of tube.", "vit": [], "exam": [], "vent": "", "abg": [], "img": "", "imgCap": "", "table": null, "q": "Which induction and which tube?", "opts": [["Ketamine 1–2 mg/kg plus rocuronium, cuffed 5.0 tube", 1, "Ketamine bronchodilates and holds the blood pressure. A cuffed tube is essential: the pressures needed to ventilate a tight chest leak around an uncuffed one. Dysphoria, hallucinations and tachycardia are the price of ketamine used for days, not of a single induction dose.", 0], ["Midazolam alone, uncuffed 5.5 tube", 0, "Light sedation invites laryngospasm, midazolam drops the blood pressure, and an uncuffed tube leaks at the peak pressures to come.", 2], ["Propofol and suxamethonium, cuffed 5.0 tube", 0, "Workable airway, wrong drug for the circulation: propofol will drop a blood pressure that is about to fall anyway when positive pressure starts.", 2], ["Awake intubation with topical anaesthesia", 0, "A struggling, hypoxic 5-year-old cannot be intubated awake. Coughing and laryngospasm will make it worse.", 3]], "teach": "Expect hypotension after the tube goes in: positive pressure plus gas trapping squeezes the venous return. Fluid first, pressor ready, and bag slowly: 8–10 breaths a minute, long exhalation.", "teachList": [], "phys": {"C": 8, "R": 60, "kg": 20, "kind": "asthma", "own": 48.0, "anc": {"set": {"iface": "MASK", "mode": "Mask", "v": {"l": 15}}, "mon": [["HR", "160"], ["RR", "48"], ["SpO₂", "86"], ["BP", "100/60"], ["Temp", "37.2 °C"]], "gas": {}}}, "rule": null, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "160"], ["RR", "48"], ["SpO₂", "86"], ["BP", "100/60"], ["Temp", "37.2 °C"]]}, {"id": "as2", "t": "Intubated · first settings", "story": "Tube in, end-tidal CO₂ confirmed, chest barely moving with the bag. He is paralysed.", "vit": [], "exam": [], "vent": "", "abg": [], "img": "", "imgCap": "", "table": null, "q": "Initial ventilator settings?", "opts": [["VC · VT 120–160 mL (6–8 mL/kg) · RR 12–14 · I:E 1:4 (Te 4–5 s) · PEEP 0–5 · FiO₂ 1.0 then titrate to SpO₂ > 90%", 1, "No mode has been shown to beat another; many start in volume control. Small breaths, enough to move the chest. A rate below the physiological rate for his age and an expiratory time of 4–5 seconds so the lungs can empty. Keep the plateau under 30.", 0], ["VC · VT 200 mL · RR 25 · I:E 1:2 · PEEP 8", 0, "A rate of 25 leaves 1.6 seconds to exhale through obstructed airways. Gas traps, the pressure climbs, the blood pressure falls.", 3], ["PC · Pinsp 35 · RR 30", 0, "Thirty-five cmH₂O driving pressure and no time to exhale. Barotrauma and trapping.", 3], ["SIMV with PS 10 at a rate of 20 to let him breathe", 0, "He is paralysed; there is nothing to support. And 20 is still too fast.", 2]], "teach": "The asthma recipe: low rate, small tidal volume, long expiratory time, plateau < 30, permissive hypercapnia with pH > 7.2. FiO₂ is rarely the problem.", "teachList": [], "phys": {"C": 7.0, "R": 91, "kg": 20, "kind": "asthma", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "VC", "v": {"vt": 140.0, "pe": 4.0, "rr": 14.0, "ti": 0.86, "o": 80}}, "mon": [["HR", "147"], ["RR", "14"], ["SpO₂", "90"], ["BP", "106/64"], ["Temp", "37.2 °C"]], "gas": {"pH": 7.21, "PaCO₂": 78.0, "PaO₂": 90.0, "HCO₃": 28.0}}, "autoA": 8.0}, "rule": {"iface": {"VENT": 0}, "knobs": {"vt": [120, 160, 100, 200], "rr": [10, 16, 8, 20], "ti": [0.6, 1.0, 0.5, 1.2], "pe": [0, 5, 0, 8], "o": [60, 100, 40, 100], "pi": [15, 25, 10, 30], "te": [3.5, 99, 2, 99]}}, "ifaces": ["VENT"], "intub": true, "mon": [["HR", "160"], ["RR", "14"], ["SpO₂", "86"], ["BP", "100/60"], ["Temp", "37.2 °C"]]}, {"id": "as3", "t": "20 minutes · the first gas", "story": "On the settings you chose. Sedated with a ketamine infusion, paralysed.", "vit": [["HR", "150"], ["SpO₂", "94%"], ["ABP", "92/55"], ["Temp", "37.0 °C"]], "exam": [], "vent": "VC · VT 140 mL · RR 14 · I:E 1:4 · PEEP 4 · FiO₂ 0.8 · PIP 42 · Pplat 24 · measured auto-PEEP 8", "abg": [["pH", "7.21"], ["PaCO₂", "78"], ["PaO₂", "90"], ["HCO₃", "28"]], "img": "", "imgCap": "", "table": null, "q": "pH 7.21, CO₂ 78. What do you do with the ventilator?", "opts": [["Nothing to the ventilator. Accept the CO₂ while pH stays above 7.2; keep the plateau under 30; continue bronchodilators and steroids", 1, "Permissive hypercapnia with pH > 7.2 is well tolerated and avoids the hyperinflation and barotrauma that chasing a normal CO₂ would cause. The peak is 42 but the plateau is 24: the gap is airway resistance, not lung stretch. Salbutamol through the circuit, steroids, and time.", 0], ["Raise the rate to 24", 0, "Less time to exhale: more trapping, a higher auto-PEEP, a lower blood pressure, and the CO₂ may actually rise.", 2], ["Raise the VT to 200 mL", 0, "The plateau climbs towards 30 and beyond. Volume delivered into trapped lungs is pressure.", 2], ["Give sodium bicarbonate", 0, "Bicarbonate makes CO₂. In a child who cannot blow it off, it worsens the respiratory acidosis.", 2]], "teach": "Peak − plateau = resistance. Plateau − PEEP = stretch. In asthma the peak is frightening and the plateau is the number that matters.", "teachList": [], "phys": {"C": 7.0, "R": 91, "kg": 20, "kind": "asthma", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "VC", "v": {"vt": 140.0, "pe": 4.0, "rr": 14.0, "ti": 0.86, "o": 80}}, "mon": [["HR", "150"], ["RR", "14"], ["SpO₂", "94"], ["ABP", "92/55"], ["Temp", "37.0 °C"]], "gas": {"pH": 7.21, "PaCO₂": 78.0, "PaO₂": 90.0, "HCO₃": 28.0}}, "autoA": 8.0}, "rule": {"iface": {"VENT": 0}, "knobs": {"vt": [120, 160, 100, 200], "rr": [10, 16, 8, 20], "ti": [0.6, 1.0, 0.5, 1.2], "pe": [0, 5, 0, 8], "o": [40, 100, 30, 100], "pi": [15, 25, 10, 30], "te": [3.5, 99, 2, 99]}}, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "150"], ["RR", "14"], ["SpO₂", "94"], ["ABP", "92/55"], ["Temp", "37.0 °C"]]}, {"id": "as4", "t": "4 hours · he starts to trigger", "story": "Paralysis has been allowed to wear off. He is taking some of his own breaths but each one seems to need a big effort before the ventilator responds.", "vit": [["HR", "140"], ["RR", "18 (set 12)"], ["SpO₂", "95%"], ["ABP", "98/60"]], "exam": [], "vent": "VC · VT 140 mL · RR 12 · I:E 1:4 · PEEP 0 · FiO₂ 0.5 · measured auto-PEEP 8 · Pplat 22", "abg": [], "img": "", "imgCap": "", "table": null, "q": "Auto-PEEP is 8 cmH₂O. What external PEEP do you set?", "opts": [["About 6 cmH₂O (roughly 75–80% of the auto-PEEP), checking that Pplat and expired volume do not worsen", 1, "With PEEP at 0 every breath begins with an 8 cmH₂O climb before the trigger even sees the effort. External PEEP just below the intrinsic PEEP splints the airways, lowers resistance and the work of triggering, without adding to the trapped volume. Recheck the plateau and auto-PEEP after the change.", 0], ["Keep PEEP at 0", 0, "Every trigger then costs 8 cmH₂O of effort. Ineffective efforts, exhaustion and asynchrony follow.", 1], ["PEEP 12", 0, "Above the intrinsic PEEP, external PEEP adds to hyperinflation. The plateau and the blood pressure both suffer.", 2], ["Paralyse him again and leave PEEP at 0", 0, "Blockade is for the first hours, at the lowest dose, stopped as soon as possible. Myopathy waits for children paralysed for days.", 1]], "teach": "External PEEP in obstruction: enough to equal or nearly equal the intrinsic PEEP, to dilate the airways, reduce resistance and reduce the work of breathing. Never above it.", "teachList": [], "phys": {"C": 6.4, "R": 60, "kg": 20, "kind": "asthma", "own": 18.0, "anc": {"set": {"iface": "VENT", "mode": "VC", "v": {"vt": 140.0, "pe": 0.0, "rr": 12.0, "ti": 1.0, "o": 50}}, "mon": [["HR", "140"], ["RR", "18"], ["SpO₂", "95"], ["ABP", "98/60"]], "gas": {}}, "trig": 18.0, "autoA": 8.0}, "rule": {"iface": {"VENT": 0}, "knobs": {"pe": [5, 7, 2, 9], "vt": [120, 160, 100, 200], "rr": [10, 16, 8, 20], "ti": [0.6, 1.0, 0.5, 1.2], "o": [30, 70, 21, 100], "te": [3.5, 99, 2, 99]}}, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "140"], ["RR", "18"], ["SpO₂", "95"], ["ABP", "98/60"]]}, {"id": "as5", "t": "Sudden desaturation", "story": "The high-pressure alarm goes off continuously. SpO₂ falls to 78%, the blood pressure to 70/40. The chest looks very full and hardly moves.", "vit": [["HR", "170"], ["SpO₂", "78%"], ["ABP", "70/40"], ["PIP", "alarm · > 50"]], "exam": [], "vent": "", "abg": [], "img": "", "imgCap": "", "table": null, "q": "First action?", "opts": [["Disconnect from the ventilator, let the chest recoil (gentle pressure on the chest), then bag slowly", 1, "Step 1 is always disconnection. If the blood pressure recovers within 30–60 seconds, the problem was trapping: restart at a lower rate and tidal volume. If it does not, go to step 2: a dislodged tube, an obstructed tube (suction it), a pneumothorax (bedside ultrasound is faster and more sensitive than a portable film), or equipment failure.", 0], ["Increase FiO₂ to 1.0 and PEEP to 10", 0, "More pressure into a chest that cannot empty. The blood pressure will fall further.", 3], ["Needle the chest immediately", 0, "Pneumothorax is on the list, but disconnection takes five seconds and tells you whether trapping is the cause. Needle a hyperinflated lung and you create the pneumothorax you were looking for.", 2], ["Bag vigorously at 40 breaths a minute", 0, "The fastest way to stack more gas. Slow, with a long pause between breaths.", 3]], "teach": "DOPE after disconnection: Displaced tube, Obstructed tube, Pneumothorax, Equipment. In asthma, add the fifth cause that comes first: trapping.", "teachList": ["Disconnect, let the chest fall, bag slowly", "Haemodynamics improve → restart with lower VT and rate", "No improvement → check the tube depth and position", "Suction the tube", "Bedside ultrasound for pneumothorax", "Swap the circuit and bag if in doubt"], "phys": {"C": 4, "R": 160, "kg": 20, "kind": "asthma", "own": 30, "anc": {"set": {"iface": "VENT", "mode": "VC", "v": {"vt": 140.0, "pe": 0.0, "rr": 12.0, "ti": 1.0, "o": 50}}, "mon": [["HR", "170"], ["RR", "12"], ["SpO₂", "78"], ["ABP", "70/40"], ["PIP", "alarm · > 50"]], "gas": {}}, "autoA": 8.0}, "rule": null, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "170"], ["RR", "12"], ["SpO₂", "78"], ["ABP", "70/40"], ["PIP", "alarm · > 50"]]}, {"id": "as6", "t": "Day 2 · keeping the gas out", "story": "Stable overnight after the disconnection and a lower rate. Salbutamol through the circuit, steroids, ketamine infusion. The blocker was stopped 12 hours ago.", "vit": [["HR", "120"], ["RR", "16 (set 12)"], ["SpO₂", "96%"], ["ABP", "100/62"]], "exam": [], "vent": "VC · VT 140 mL · RR 12 · I:E 1:4 · PEEP 6 · FiO₂ 0.4 · Pplat 20 · auto-PEEP 3", "abg": [["pH", "7.36"], ["PaCO₂", "50"], ["PaO₂", "95"], ["HCO₃", "28"]], "img": "", "imgCap": "", "table": null, "q": "What keeps the auto-PEEP away and gets him to extubation?", "opts": [["Keep the long expiratory time, small VT, bronchodilators and adequate sedation; no routine blocker; wean the rate as the CO₂ falls; extubate once he is awake and the chest is quiet", 1, "The four ways to prevent auto-PEEP: a long expiratory time, bronchodilators, sedation that stops him fighting, and a low tidal volume. The blocker stays off. Weaning in asthma is usually fast: as the airways open, the trapped volume falls, and a child who was unventilatable yesterday is often extubated within 24–48 hours.", 0], ["Keep a blocker infusion for 48 hours for safety", 0, "Steroids plus a neuromuscular blocker for days is the recipe for critical-illness myopathy. Stop it as soon as he is synchronous.", 2], ["Raise the rate to 24 now that the CO₂ is only 50", 0, "Shortening expiration brings the auto-PEEP straight back. CO₂ 50 with pH 7.36 does not need fixing.", 2], ["Extubate now while he is deeply sedated", 0, "Extubation needs an awake child with a clear chest, a leak around the tube and a plan for laryngospasm. Not a sleeping one.", 3]], "teach": "Prevent auto-PEEP: prolonged expiratory time, bronchodilators, sedation, low tidal volume. All four, every shift.", "teachList": [], "phys": {"C": 10.0, "R": 60, "kg": 20, "kind": "asthma", "own": 16.0, "anc": {"set": {"iface": "VENT", "mode": "VC", "v": {"vt": 140.0, "pe": 6.0, "rr": 12.0, "ti": 1.0, "o": 40}}, "mon": [["HR", "120"], ["RR", "16"], ["SpO₂", "96"], ["ABP", "100/62"]], "gas": {"pH": 7.36, "PaCO₂": 50.0, "PaO₂": 95.0, "HCO₃": 28.0}}, "trig": 16.0, "autoA": 3.0}, "rule": {"iface": {"VENT": 0}, "knobs": {"vt": [120, 160, 100, 200], "rr": [10, 16, 8, 20], "ti": [0.6, 1.0, 0.5, 1.2], "pe": [3, 7, 0, 8], "o": [25, 60, 21, 100], "te": [3.5, 99, 2, 99]}}, "ifaces": ["VENT"], "intub": false, "mon": [["HR", "120"], ["RR", "16"], ["SpO₂", "96"], ["ABP", "100/62"]]}], "debrief": ["Intubation in asthma is a clinical decision: exhaustion and altered mental state, not a gas.", "Ketamine, a cuffed tube, fluid first, pressor ready. Expect hypotension when positive pressure starts.", "Low rate, small VT, I:E 1:4, expiratory time 4–5 s, plateau < 30, pH > 7.2.", "Peak − plateau is resistance; plateau − PEEP is stretch. Watch the plateau.", "External PEEP at or just below the intrinsic PEEP once he triggers; never above it.", "Sudden collapse: disconnect first, then DOPE. Ultrasound before the X-ray.", "Prevent auto-PEEP: long expiration, bronchodilators, sedation, low VT. Blockade shortest and lowest."], "pocus": {"heart": ["assets/pocus/a4c-normal.mp4", "Apical four-chamber: normal function; small, underfilled ventricles."], "ivc": ["assets/pocus/ivc-normal.mp4", "IVC normal size."], "subcostal": ["assets/pocus/subcostal-normal.mp4", "Subcostal: no pericardial effusion."], "lung": [null, "A-lines with lung sliding on both sides: no pneumothorax."]}}]};
